INSERT INTO `test_series_subjects` (`id`, `test_id`, `subject_id`, `question_count`, `created_at`, `updated_at`) VALUES ('3', '3', '3', '5', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('1', '1', '1', 'A vehicle accelerates uniformly from rest to a speed of 72 km/h in 10 seconds. What is the distance traversed in this interval?', NULL, '{\"a\":\"100 meters\",\"b\":\"200 meters\",\"c\":\"50 meters\",\"d\":\"150 meters\"}', 'a', '4.00', '1.00', 'Speed = 72 km/h = 72 × (5/18) = 20 m/s. Acceleration a = (v - u)/t = 20/10 = 2 m/s². Distance s = ut + 0.5at² = 0 + 0.5 × 2 × 100 = 100 meters.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('2', '1', '1', 'Which of the following physical quantities has the same dimensions as Planck\'s constant (h)?', NULL, '{\"a\":\"Force \\u00d7 Velocity\",\"b\":\"Angular Momentum\",\"c\":\"Linear Momentum\",\"d\":\"Energy \\u00d7 Time\\u00b2\"}', 'b', '4.00', '1.00', 'Dimensions of Planck\'s constant h = [M L² T⁻¹]. Angular momentum L = mvr = [M][L][L T⁻¹] = [M L² T⁻¹]. Thus both possess identical dimensional formulas.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('3', '1', '1', 'A body of mass 5 kg is sliding down an inclined plane of 30° at a constant velocity. What is the coefficient of kinetic friction (μk)?', NULL, '{\"a\":\"1 \\/ \\u221a3 (\\u2248 0.577)\",\"b\":\"\\u221a3 \\/ 2 (\\u2248 0.866)\",\"c\":\"0.500\",\"d\":\"1.000\"}', 'a', '4.00', '1.00', 'When a body moves down an inclined plane at constant velocity, acceleration is zero: mg sin(θ) = μk mg cos(θ). Therefore μk = tan(θ) = tan(30°) = 1/√3.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('4', '1', '1', 'In a conservative force field, the work done along any closed path is always equal to:', NULL, '{\"a\":\"Positive infinity\",\"b\":\"Dependent on the path chosen\",\"c\":\"Zero\",\"d\":\"Total mechanical energy of the system\"}', 'c', '4.00', '1.00', 'By fundamental definition, the line integral of a conservative force over any closed loop is identically zero: ∮ F · dr = 0.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('5', '1', '1', 'The escape velocity from the surface of the Earth is approximately 11.2 km/s. If a projectile is fired at 45° to the horizontal, its escape velocity will be:', NULL, '{\"a\":\"11.2 \\u00d7 sin(45\\u00b0) km\\/s\",\"b\":\"11.2 km\\/s\",\"c\":\"11.2 \\u00d7 \\u221a2 km\\/s\",\"d\":\"22.4 km\\/s\"}', 'b', '4.00', '1.00', 'Escape velocity ve = √(2GM/R) is completely independent of the projection angle. Hence it remains 11.2 km/s regardless of whether it is launched vertically or at 45°.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('6', '2', '4', 'Which cell organelle is responsible for the synthesis of steroidal hormones and lipid metabolism in animal cells?', NULL, '{\"a\":\"Rough Endoplasmic Reticulum\",\"b\":\"Smooth Endoplasmic Reticulum (SER)\",\"c\":\"Golgi Apparatus\",\"d\":\"Peroxisomes\"}', 'b', '4.00', '1.00', 'The Smooth Endoplasmic Reticulum (SER) is the major site for synthesis of lipids and steroidal hormones in animal cells.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('7', '2', '4', 'During which phase of Meiosis I does the process of crossing over (genetic recombination) occur?', NULL, '{\"a\":\"Leptotene\",\"b\":\"Zygotene\",\"c\":\"Pachytene\",\"d\":\"Diplotene\"}', 'c', '4.00', '1.00', 'Crossing over takes place at the Pachytene stage of Prophase I, mediated by the recombinase enzyme complex between non-sister chromatids.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('8', '2', '4', 'Which of the following is considered the universal electron acceptor in anaerobic glycolysis?', NULL, '{\"a\":\"Oxygen\",\"b\":\"NAD\\u207a\",\"c\":\"FAD\",\"d\":\"Cytochrome c\"}', 'b', '4.00', '1.00', 'In glycolysis, NAD⁺ acts as the oxidizing agent accepting electrons during the conversion of glyceraldehyde 3-phosphate to 1,3-bisphosphoglycerate.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('9', '2', '4', 'The functional unit of human kidney where selective reabsorption and ultrafiltration occur is called:', NULL, '{\"a\":\"Neuron\",\"b\":\"Nephron\",\"c\":\"Alveolus\",\"d\":\"Hepatic Lobule\"}', 'b', '4.00', '1.00', 'Each human kidney contains approximately one million complex tubular structures called nephrons, which are the functional filtration units.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('10', '2', '4', 'According to the competitive inhibition model, an increase in substrate concentration results in:', NULL, '{\"a\":\"Reduction of Km with constant Vmax\",\"b\":\"Overcoming the inhibitor effect, reaching normal Vmax\",\"c\":\"Permanent denaturation of enzyme\",\"d\":\"Decrease in both Vmax and Km\"}', 'b', '4.00', '1.00', 'In competitive inhibition, Vmax remains unchanged because a high concentration of substrate outcompetes the inhibitor for the active site, while Km increases.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('11', '4', '1', 'The moment of inertia of a uniform solid sphere of mass M and radius R about its diametrical axis is:', NULL, '{\"a\":\"(1\\/2) M R\\u00b2\",\"b\":\"(2\\/5) M R\\u00b2\",\"c\":\"(2\\/3) M R\\u00b2\",\"d\":\"(7\\/5) M R\\u00b2\"}', 'b', '4.00', '1.00', 'For a solid sphere about a central axis through its diameter, I = (2/5) M R². For a hollow spherical shell it is (2/3) M R².', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('12', '4', '1', 'A Carnot engine operating between 500 K and 300 K has an ideal thermodynamic efficiency of:', NULL, '{\"a\":\"40%\",\"b\":\"60%\",\"c\":\"20%\",\"d\":\"30%\"}', 'a', '4.00', '1.00', 'Efficiency η = 1 - (T_cold / T_hot) = 1 - (300 / 500) = 1 - 0.6 = 0.40, which corresponds to 40%.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('13', '5', '2', 'What is the hybridization state of the central carbon in the carbocation intermediate formed during SN1 reactions?', NULL, '{\"a\":\"sp\",\"b\":\"sp\\u00b2\",\"c\":\"sp\\u00b3\",\"d\":\"sp\\u00b3d\"}', 'b', '4.00', '1.00', 'A carbocation intermediate possesses three bonded groups and an empty p-orbital, adopting a planar geometry with sp² hybridization.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('14', '5', '2', 'Which of the following compounds will exhibit highest nucleophilic addition reactivity towards HCN?', NULL, '{\"a\":\"Formaldehyde (HCHO)\",\"b\":\"Acetaldehyde (CH\\u2083CHO)\",\"c\":\"Acetone (CH\\u2083COCH\\u2083)\",\"d\":\"Acetophenone (C\\u2086H\\u2085COCH\\u2083)\"}', 'a', '4.00', '1.00', 'HCHO has no electron donating alkyl groups and minimal steric hindrance, leaving its carbonyl carbon highly electrophilic.', '2026-11-25 08:28:21', '2026-11-25 08:28:21');
